package com.badlogic.gdx.graphics.g3d.decals;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.g2d.TextureRegion;

/** Material used by the {@link Decal} class */
public class DecalMaterial {
  public static final int NO_BLEND = -1;

  // Initialized to a non-null dummy region to satisfy NullAway; real code should
  // set this to a meaningful TextureRegion via Decal#setTextureRegion or a custom material.
  protected TextureRegion textureRegion = new TextureRegion();

  protected int srcBlendFactor;
  protected int dstBlendFactor;

  /**
   * Binds the material's texture to the OpenGL context and changes the glBlendFunc to the values
   * used by it.
   */
  public void set() {
    textureRegion.getTexture().bind(0);
    if (!isOpaque()) {
      Gdx.gl.glBlendFunc(srcBlendFactor, dstBlendFactor);
    }
  }

  /**
   * @return true if the material is completely opaque, false if it is not and therefor requires
   *     blending
   */
  public boolean isOpaque() {
    return srcBlendFactor == NO_BLEND;
  }

  public int getSrcBlendFactor() {
    return srcBlendFactor;
  }

  public int getDstBlendFactor() {
    return dstBlendFactor;
  }

  @Override
  public boolean equals(Object o) {
    if (o == null) return false;

    DecalMaterial material = (DecalMaterial) o;

    return dstBlendFactor == material.dstBlendFactor
        && srcBlendFactor == material.srcBlendFactor
        && textureRegion.getTexture() == material.textureRegion.getTexture();
  }

  @Override
  public int hashCode() {
    int result = textureRegion.getTexture() != null ? textureRegion.getTexture().hashCode() : 0;
    result = 31 * result + srcBlendFactor;
    result = 31 * result + dstBlendFactor;
    return result;
  }
}
